cd "$RUN/work" && python3 - <<'EOF'
p='index.html'
s=open(p).read()
s=s.replace('''              <div class="day" style="grid-column:2"><span>Mon</span><b class="">26</b></div>
              <div class="day today" style="grid-column:2"></div>
''','''              <div class="day today" style="grid-column:2"><span>Mon</span><b>26</b></div>
''')
s=s.replace('''        el.classList.add('in');
        io.unobserve(el);''','''        el.classList.add('in');
        el.addEventListener('transitionend', function done(ev) {
          if (ev.target !== el || ev.propertyName !== 'opacity') return;
