input.command:
cd "$RUN/work" && sed -i '' 's/    .hero-grid { grid-template-columns: 1fr; gap: var(--space-7); }/    .hero-grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-7); }/' index.html && grep -n "hero-grid { grid-template-columns: minmax" index.html && D=/tmp/rotaline-shots.4Tm4 && grep -v 'fonts.g' index.html > $D/test.html && python3 - <<'EOF'
D='/tmp/rotaline-shots.4Tm4/'
s=open(D+'test.html').read()
dbg='''<script>
window.addEventListener('load',function(){var W=document.documentElement.clientWidth;var out=['W='+W+' sw='+document.documentElement.scrollWidth];
document.querySelectorAll('body *').forEach(function(el){if(el.closest('svg'))return;var r=el.getBoundingClientRect();if(r.width&&r.right>W-20+1){out.push(el.tagName+'.'+el.className+' r='+Math.round(r.right)+' w='+Math.round(r.width))}
 if(el.scrollWidth>el.clientWidth+1&&el.clientWidth>0&&getComputedStyle(el).overflow==='visible')out.push('SW '+el.tagName+'.'+el.className+' '+el.scrollWidth+'>'+el.clientWidth)});
var p=document.createElement('pre');p.id='dbg';p.textContent=out.slice(0,40).join('\\n');document.body.appendChild(p);parent.postMessage(p.textContent,'*');});
</script></body>'''
open(D+'dbg.html','w').write(s.replace('</body>',dbg))
EOF
C="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"; rm -f $D/dom.txt; "$C" --headless=new --user-data-dir=$D/prof2 --disable-gpu --window-size=600,900 --virtual-time-budget=3000 --dump-dom "file://$D/dframe.html" > $D/dom.txt 2>/dev/null & PID=$!; for i in $(seq 1 25); do grep -q '</html>' $D/dom.txt 2>/dev/null && break; sleep 1; done; kill $PID 2>/dev/null; sed -n '/<pre id="out">/,/<\/pre>/p' $D/dom.txt | head -45

